cat > build.py << 'EOF'
import numpy as np
R=1.39; RH=2.47
atoms=[]
def add(el,p): atoms.append((el,np.array(p,float)))
add('Ag',[0,0,0])
# ---- pydc in xy-plane, N on -x ----
sx=0.2
c=np.array([-3.74+sx,0,0])
def pxy(ang,r=R): return c+np.array([r*np.cos(np.radians(ang)),r*np.sin(np.radians(ang)),0])
add('N',pxy(0))
for a in (60,120,180,240,300): add('C',pxy(a))
for a in (120,180,240): add('H',pxy(a,RH))
for sgn in (1,-1):
    C2=pxy(60*sgn)
    C7=C2+1.5*np.array([np.cos(np.radians(60)),sgn*np.sin(np.radians(60)),0])
    O1=C7+1.27*np.array([1,0,0])
    O2=C7+1.24*np.array([np.cos(np.radians(120)),sgn*np.sin(np.radians(120)),0])
    add('C',C7); add('O',O1); add('O',O2)
# ---- terpy in xz-plane, central N on +x ----
tx=-0.2
cc=np.array([3.74+tx,0,0])
def pxz(cen,ang,r=R): return cen+np.array([r*np.cos(np.radians(ang)),0,r*np.sin(np.radians(ang))])
add('N',pxz(cc,180))
for a in (120,60,0,-60,-120): add('C',pxz(cc,a))
for a in (60,0,-60): add('H',pxz(cc,a,RH))
for sgn in (1,-1):
    oc=np.array([1.61+tx,0,3.69*sgn])
    # vertices: C2'' at 300, N at 240, C6 180, C5 120, C4 60, C3 0 (mirror for sgn=-1)
    def q(ang,r=R): return pxz(oc, ang*sgn, r)
    add('C',q(300)); add('N',q(240))
    for a in (180,120,60,0): add('C',q(a))
    for a in (180,120,60,0): add('H',q(a,RH))
with open('init.xyz','w') as f:
    f.write(f"{len(atoms)}\nAg(pydc)(terpy) initial\n")
    for el,p in atoms: f.write(f"{el} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
print(len(atoms))
EOF
python3 build.py
